export const catalogKey = (name) => name.toLowerCase().replace(/[^a-z0-9]+/g, '');
const slug = (s) => s.toLowerCase().replace(/[^a-z0-9]+/g, '-').replace(/^-|-$/g, '');
export const GYM_CATALOG = RAW.split('\n').map((line) => {
    const [cat, gear, name, unit] = line.split('|');
    return { id: `gc-${slug(name)}`, name, cat, gear, unit: (unit === 'sec' || unit === 'min' ? unit : 'reps') };
});
/** The app's own library entries first, then every catalogue entry whose name isn't already there. */
export function mergeCatalog(own) {
    const have = new Set(own.map((e) => catalogKey(e.name)));
    return [...own, ...GYM_CATALOG.filter((c) => !have.has(catalogKey(c.name)))];
}
